"""Expected-tools types and YAML parsing for the eval suite.

``gate`` on an ``expected_tools`` entry controls whether a mismatch fails the run:

- ``gate: true`` — **required for pass**. When tool-call metrics are enabled, the
  entry must match perfectly (``accuracy == 1.0``) or the scenario run fails.
  Failures appear under ``--- Assertion Results ---``.
- ``gate: false`` or omitted — **informational only**. The entry is still scored
  and shown under ``--- Tool Call Metrics ---``, but does not affect pass/fail.

This is unrelated to Mantle tool ``requires:`` gates (runtime tool availability).
"""

from __future__ import annotations

from typing import Any

from pydantic import BaseModel, ConfigDict, Field

from rasa.builder.copilot.mcp_server.tools.eval_errors import EvalScenarioError

_TOOL_CALLED_KEY = "tool_called"
_STANDALONE_EXPECTED_TOOLS_KEYS = frozenset({"tool_called", "gate"})


class ExpectedTool(BaseModel):
    """One expected MCP tool (standalone ``tool_called`` list entry)."""

    model_config = ConfigDict(frozen=True)

    tool_name: str
    arguments: dict[str, Any] | None = None
    gate: bool = False


class ExpectedToolGroup(BaseModel):
    """Multiple expected tools that must co-occur on one user turn."""

    model_config = ConfigDict(frozen=True)

    tools: list[ExpectedTool] = Field(default_factory=list)
    ordered: bool = False
    gate: bool = False


def _parse_tool_called_value(
    value: Any, *, location: str
) -> tuple[str, dict[str, Any] | None]:
    """Parse a ``tool_called`` value into tool name and optional arguments."""
    if isinstance(value, str):
        tool_name = value.strip()
        arguments = None
    elif isinstance(value, dict):
        tool_name_raw = value.get("tool_name")
        if not isinstance(tool_name_raw, str) or not tool_name_raw.strip():
            raise EvalScenarioError(
                f"{location}: tool_called map must include a non-empty tool_name string"
            )
        tool_name = tool_name_raw.strip()
        arguments_raw = value.get("arguments")
        if arguments_raw is None:
            arguments = None
        elif not isinstance(arguments_raw, dict):
            raise EvalScenarioError(
                f"{location}: tool_called arguments must be a map of parameter names "
                "to values"
            )
        else:
            arguments = dict(arguments_raw)
    else:
        raise EvalScenarioError(
            f"{location}: tool_called must be a tool name string or a map with "
            f"tool_name, got: {value!r}"
        )

    if not tool_name:
        raise EvalScenarioError(
            f"{location}: tool_called must be a non-empty tool name string"
        )
    return tool_name, arguments


def _require_boolean_flag(value: Any, *, location: str, field_name: str) -> bool:
    """Return a boolean tool_group list flag after validation."""
    if not isinstance(value, bool):
        raise EvalScenarioError(
            f"{location}.{field_name} must be a boolean, got: {value!r}"
        )
    return value


def _parse_tool_group_list_item(item: Any, *, item_location: str) -> tuple[str, Any]:
    """Return ``(key, value)`` for one validated tool_group list entry."""
    if not isinstance(item, dict) or len(item) != 1:
        raise EvalScenarioError(
            f"{item_location} must be a single-key map, got: {item!r}"
        )
    return next(iter(item.items()))


def _collect_tool_group_spec(
    items_raw: list[Any], *, location: str
) -> tuple[bool, bool, list[dict[str, Any]]]:
    """Parse ordered/gate flags and tool_called entries from a tool_group list."""
    ordered = False
    gate = False
    tool_items: list[dict[str, Any]] = []

    for item_index, item in enumerate(items_raw):
        item_location = f"{location}[{item_index}]"
        key, item_value = _parse_tool_group_list_item(item, item_location=item_location)
        if key == "ordered":
            ordered = _require_boolean_flag(
                item_value, location=item_location, field_name="ordered"
            )
        elif key == "gate":
            gate = _require_boolean_flag(
                item_value, location=item_location, field_name="gate"
            )
        elif key == "tool_called":
            tool_items.append(item)
        else:
            raise EvalScenarioError(
                f"{item_location} has unsupported key {key!r}; expected one of "
                "ordered, gate, or tool_called"
            )

    if not tool_items:
        raise EvalScenarioError(
            f"{location} must include at least one tool_called entry"
        )

    return ordered, gate, tool_items


def _build_expected_tools_from_items(
    tool_items: list[dict[str, Any]], *, location: str
) -> list[ExpectedTool]:
    """Build ``ExpectedTool`` instances from collected tool_group tool_called maps."""
    tools: list[ExpectedTool] = []
    for tool_index, tool_item in enumerate(tool_items):
        item_location = f"{location}[{tool_index}]"
        tool_name, arguments = _parse_tool_called_value(
            tool_item["tool_called"], location=item_location
        )
        tools.append(ExpectedTool(tool_name=tool_name, arguments=arguments))
    return tools


def _parse_expected_tool_group(entry: dict[str, Any], index: int) -> ExpectedToolGroup:
    """Parse one ``expected_tools`` entry with a ``tool_group`` key."""
    if len(entry) != 1:
        raise EvalScenarioError(
            f"expected_tools[{index}] tool_group entries must "
            f"contain only tool_group, got: {sorted(entry.keys())}"
        )
    location = f"expected_tools[{index}].tool_group"
    items_raw = entry["tool_group"]
    if not isinstance(items_raw, list) or not items_raw:
        raise EvalScenarioError(f"{location} must be a non-empty list")

    ordered, gate, tool_items = _collect_tool_group_spec(items_raw, location=location)
    tools = _build_expected_tools_from_items(tool_items, location=location)
    return ExpectedToolGroup(tools=tools, ordered=ordered, gate=gate)


def _parse_expected_tool(entry: dict[str, Any], index: int) -> ExpectedTool:
    """Parse one standalone ``expected_tools`` entry with ``tool_called``."""
    location = f"expected_tools[{index}]"
    extra_keys = set(entry.keys()) - _STANDALONE_EXPECTED_TOOLS_KEYS
    if extra_keys:
        raise EvalScenarioError(
            f"{location} standalone tool_called entries may only include "
            f"tool_called and gate, got: {sorted(entry.keys())}"
        )

    gate_raw = entry.get("gate", False)
    if not isinstance(gate_raw, bool):
        raise EvalScenarioError(f"{location}.gate must be a boolean, got: {gate_raw!r}")
    tool_name, arguments = _parse_tool_called_value(
        entry["tool_called"], location=location
    )
    return ExpectedTool(tool_name=tool_name, arguments=arguments, gate=gate_raw)


def parse_expected_tools(value: Any) -> list[ExpectedTool | ExpectedToolGroup]:
    """Parse raw YAML ``expected_tools`` into validated entries."""
    if value is None or value == []:
        return []
    if value in ("", {}, ()):
        raise EvalScenarioError(
            "expected_tools must be a list of tool assertions or omitted, "
            f"got: {value!r}"
        )
    if not isinstance(value, list):
        raise EvalScenarioError(
            f"expected_tools must be a list, got: {type(value).__name__}"
        )

    parsed: list[ExpectedTool | ExpectedToolGroup] = []
    for index, entry in enumerate(value):
        if not isinstance(entry, dict):
            raise EvalScenarioError(
                f"expected_tools[{index}] must be a map, got: {entry!r}"
            )

        if "tool_group" in entry:
            parsed.append(_parse_expected_tool_group(entry, index))
            continue

        if "tool_called" in entry:
            parsed.append(_parse_expected_tool(entry, index))
            continue

        raise EvalScenarioError(
            f"expected_tools[{index}] must be a standalone tool_called or "
            f"a tool_group, got: {entry!r}"
        )

    return parsed
